UPDATE lottery_draws SET draw_time = '20:50' WHERE id = 'draw-lei-quiniela';
UPDATE lottery_draws SET draw_time = '19:50' WHERE id = 'draw-lot-quiniela';
UPDATE lottery_draws SET draw_time = '19:00' WHERE id = 'draw-pri-noche';
UPDATE lottery_draws SET draw_time = '22:45' WHERE id = 'draw-fl-noche';
-- Reglas sin montos de pago.
UPDATE lottery_draws SET how_to_play = 'Salen 3 números del 00 al 99: primer, segundo y tercer premio. Quiniela: aciertas uno de los tres números. Palé: aciertas dos. Tripleta: aciertas los tres. El premio depende de la jugada y del premio en que salga tu número.' WHERE how_to_play LIKE 'Salen 3 números del 00 al 99: primer%';
UPDATE lottery_draws SET how_to_play = 'Eliges hasta 10 números del 1 al 84 y en el sorteo salen 20. Se gana desde 5 aciertos y el premio mayor es acertar 10 de 10.' WHERE id = 'draw-lei-superkino';
UPDATE lottery_draws SET how_to_play = 'Eliges 6 números del 1 al 40. El premio mayor es acertar los 6, y hay premios menores por menos aciertos según las reglas de la lotería. Loto Más y Súper Más añaden bolos adicionales.' WHERE id = 'draw-lei-loto';
UPDATE lottery_draws SET how_to_play = 'Eliges 6 números del 1 al 38. El premio mayor es acertar los 6, y hay premios menores por menos aciertos según las reglas de la lotería.' WHERE id = 'draw-rea-loto';
UPDATE lottery_draws SET how_to_play = 'Salen 5 números del 00 al 99. Se gana desde 2 aciertos y el premio crece con más aciertos, según la jugada.' WHERE id = 'draw-lot-megachances';
